// Split the URL list by platform so each Apify Actor is called once with a batch.
const urls = $input.first().json.urls.map(u => String(u).trim()).filter(Boolean);
const isTikTok = u => /tiktok\.com/i.test(u);
const out = [];
const youtube = urls.filter(u => !isTikTok(u));
const tiktok = urls.filter(isTikTok);
if (youtube.length) out.push({ json: { platform: 'youtube', actor: 'tubetext~youtube-transcript-fast', input: { urls: youtube, aiFallback: true } } });
if (tiktok.length) out.push({ json: { platform: 'tiktok', actor: 'tubetext~tiktok-transcript', input: { urls: tiktok } } });
return out;

const contentField = "transcript";
const requestNodeName = "Split links by platform";
const defaultActor = "";
// contentField, requestNodeName and defaultActor are fixed by this template.
// No IO: classify complete HTTP responses and keep failed data out of content fields.
const output = [];
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = value => typeof value === 'string' && value.trim().length > 0;
const presentError = value => value !== undefined && value !== null && value !== false &&
  (typeof value !== 'string' || text(value));
const errorMessage = value => text(value) ? value : object(value) && text(value.message) ? value.message : '';
const timeout = value => /timed[ -]?out|timeout|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(value);
const scalar = value => value == null || typeof value === 'string' || typeof value === 'boolean' ||
  (typeof value === 'number' && Number.isFinite(value));
const timeValue = value => (typeof value === 'number' || text(value)) && Number.isFinite(Number(value));
const recovery = (...sources) => {
  const result = {};
  for (const source of sources) if (object(source)) {
    for (const key of ['runId', 'actorRunId', 'datasetId', 'defaultDatasetId', 'runStatus']) {
      if (text(source[key])) result[key] = source[key];
    }
    if (typeof source.charged === 'boolean') result.charged = source.charged;
  }
  return result;
};
for (let responseIndex = 0; responseIndex < $input.all().length; responseIndex++) {
  let response = $input.all()[responseIndex].json || {};
  let responseParseError = false;
  // The HTTP node retains text plus headers/status before parsing. Keep its output intact.
  if (typeof response.body === 'string') {
    try { response = { ...response, body: JSON.parse(response.body) }; }
    catch { responseParseError = true; }
  }
  let context = {}, contextUnavailable = false;
  try { context = $(requestNodeName).itemMatching(responseIndex).json || {}; }
  catch { contextUnavailable = true; } // Never borrow another batch's input or recovery IDs.
  const requestUrls = [...new Set((context.input?.urls || context.urls || []).filter(text))];
  const responseHeaders = response.headers || response.error?.response?.headers || response.error?.headers;
  const headers = Object.fromEntries(Object.entries(object(responseHeaders) ? responseHeaders : {}).map(([k, v]) => [k.toLowerCase(), v]));
  const statusValue = response.statusCode ?? response.error?.statusCode ?? response.error?.httpCode ??
    response.error?.response?.statusCode ?? response.error?.response?.status;
  const httpStatus = Number.isInteger(statusValue) ? statusValue :
    typeof statusValue === 'string' && /^\d{3}$/.test(statusValue) ? Number(statusValue) : undefined;
  const headerIds = {
    runId: headers['x-apify-actor-run-id'],
    datasetId: headers['x-apify-default-dataset-id'] || headers['x-apify-dataset-id'],
  };
  const base = {
    ...recovery(headerIds, response, response.error?.response?.body, response.error, response.body, response.body?.error),
    actor: context.actor || defaultActor, responseIndex, requestUrls,
    ...(text(context.platform) ? { platform: context.platform } : {}),
    ...(contextUnavailable ? { contextUnavailable: true } : {}),
    ...(httpStatus !== undefined ? { httpStatus } : {}),
    ...(responseParseError ? { responseParseError: 'invalid_json' } : {}),
  };
  const emit = json => output.push({ json, pairedItem: { item: responseIndex } });
  const fail = (status, code, message, row = {}, resultIndex) => {
    const json = { ...base, ...recovery(row, row.error), _routeToContent: false,
      status, errorCode: text(row.errorCode) ? row.errorCode : code,
      error: errorMessage(row.error) || message };
    for (const key of ['input', 'url', 'videoId']) if (text(row[key])) json[key] = row[key];
    if (text(row.status)) json.actorStatus = row.status;
    if (resultIndex !== undefined) json.resultIndex = resultIndex;
    emit(json); // Explicit whitelist: no transcript, summary, headers or arbitrary error objects.
  };
  if (presentError(response.error)) {
    const message = errorMessage(response.error) || 'HTTP request failed; inspect the existing run before retrying.';
    const code = text(response.error?.code) ? response.error.code : 'request_failed';
    const isTimeout = timeout(message) || timeout(code) || httpStatus === 408 || httpStatus === 504;
    fail(isTimeout ? 'timeout' : 'transport_error', code, message);
    continue;
  }
  if (httpStatus === undefined || httpStatus < 200 || httpStatus >= 300) {
    const isTimeout = httpStatus === 408 || httpStatus === 504;
    fail(isTimeout ? 'timeout' : 'http_error', isTimeout ? 'request_timeout' : 'http_error',
      errorMessage(response.body?.error) || `HTTP ${httpStatus ?? 'status missing'}; inspect the existing run before retrying.`);
    continue;
  }
  if (responseParseError) {
    fail('invalid_result', 'invalid_json', 'Response body is not valid JSON. Inspect the retained HTTP response and existing run before retrying.');
    continue;
  }
  if (!Array.isArray(response.body)) {
    fail('invalid_result', 'invalid_dataset_response', 'Expected a dataset array; no content was forwarded.');
    continue;
  }
  if (!response.body.length) {
    fail('missing_result', 'empty_dataset', 'The response contained no dataset rows. Inspect the existing run before retrying.');
    continue;
  }
  const linked = new Set();
  response.body.forEach((row, resultIndex) => {
    if (!object(row)) { fail('invalid_result', 'invalid_row', 'Dataset row is not an object.', {}, resultIndex); return; }
    for (const key of ['input', 'url']) if (text(row[key])) linked.add(row[key]);
    if (row.status !== 'ok' || presentError(row.error) || presentError(row.errorCode)) {
      fail(text(row.status) && row.status !== 'ok' ? row.status : 'error', 'actor_result_failed',
        `Actor result is not successful (status: ${text(row.status) ? row.status : 'missing'}).`, row, resultIndex);
      return;
    }
    if (!text(row[contentField])) {
      fail('missing_result', 'missing_content', `Successful status without a nonempty ${contentField} string.`, row, resultIndex);
      return;
    }
    const validBeat = value => object(value) && typeof value.beat === 'string' &&
      typeof value.description === 'string' && timeValue(value.start) && timeValue(value.end);
    const validMoment = value => object(value) && typeof value.what === 'string' && timeValue(value.time);
    if (contentField === 'summary' && [['structure', validBeat], ['keyMoments', validMoment]].some(([key, valid]) =>
      row[key] != null && (!Array.isArray(row[key]) || !row[key].every(valid)))) {
      fail('invalid_result', 'invalid_analysis_lists', 'Analysis lists have an invalid shape.', row, resultIndex);
      return;
    }
    // Validate every value read by the existing Set formatters before casting/concatenating.
    // Keep printable legacy values (including numeric time strings) unchanged.
    const fields = contentField === 'summary' ? [row.url || row.input, row.author || '',
      row.playCount ?? '', row.engagementRate ?? '', row.format || '', row.tone || '', row.hook?.text || '',
      row.shotCount ?? '', row.cta || '', row.audience || '', row.onScreenText || '', row.transcript || ''] :
      [row.url || row.input, row.title || row.description || '', row.channelName || row.authorUsername || '', row.source || '', row.wordCount || 0];
    if (!fields.every(scalar) || (contentField === 'transcript' && !Number.isFinite(Number(row.wordCount || 0)))) {
      fail('invalid_result', 'invalid_formatter_fields', 'Content metadata has an invalid shape for the formatter.', row, resultIndex);
      return;
    }
    emit({ ...row, _routeToContent: true }); // The success formatter retains the original public fields.
  });
  for (const url of requestUrls) if (!linked.has(url)) {
    fail('missing_result', 'input_result_not_linked',
      'No returned row could be linked to this input. Check aliases and the existing dataset before retrying.', { input: url, url });
  }
}
return output;
